import {escapeHTML as e} from '../../shared/primitives.js';
import {avatar,icon,pageHeading,badge,empty} from '../../shared/ui.js';
const locationName=(c,id)=>c.locations.find(l=>l.id===id)?.name||'Local desconhecido';
const button=(action,label,primary=false)=>`<button class="${primary?'primary':''}" data-action="${action}">${icon('plus')}${label}</button>`;
export function chapterView(c,selectedId) {
 const ch=c.chapters.find(v=>v.id===selectedId)||c.chapters.at(-1);
 return `${pageHeading('O ARQUIVO DA CAMPANHA','Capítulos','Escreva, revise e preserve cada parte da sua história.',button('new-chapter','Novo capítulo',true))}<div class="chapter-layout"><aside class="chapter-index"><div class="eyebrow">A CRÔNICA · ${c.chapters.length} CAPÍTULOS</div>${c.chapters.map((v,i)=>`<button class="chapter-item ${v.id===ch?.id?'active':''}" data-chapter="${e(v.id)}"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><div><strong>${e(v.title)}</strong><small>${e(v.period)}</small>${badge(v.status)}</div></button>`).join('')}</aside>${ch?`<article class="chapter-paper"><div class="section-line"><span class="eyebrow">${e(ch.period)}</span><div><button data-edit-chapter="${e(ch.id)}">Editar texto</button><button class="quiet" data-export-chapter="${e(ch.id)}" title="Baixar capítulo em Markdown">↓ .md</button></div></div><h2>${e(ch.title)}</h2>${badge(ch.status)}<div class="prose">${e(ch.body)}</div><div class="linked-characters"><div class="eyebrow">PERSONAGENS DESTE CAPÍTULO</div><div>${ch.characterIds.map(id=>{const char=c.characters.find(v=>v.id===id);return char?`<button class="character-chip" data-open-character="${e(id)}">${avatar(char)}${e(char.name)}</button>`:'';}).join('')||'<p class="muted">Nenhum vínculo registrado.</p>'}</div></div></article>`:empty('Uma história por escrever','Crie o primeiro capítulo para começar o arquivo.')}</div>`;
}
